<?php
namespace Database\Seeders; use App\Models\{Supplier,Product,StockMovement,Order}; use Illuminate\Database\Seeder;
class DatabaseSeeder extends Seeder {public function run():void{$s1=Supplier::create(['name'=>'TechSupply Europe','email'=>'contact@techsupply.test','contact_name'=>'Maya Laurent']);$s2=Supplier::create(['name'=>'OfficeHub','email'=>'sales@officehub.test','contact_name'=>'Hugo Bernard']);$p1=Product::create(['supplier_id'=>$s1->id,'sku'=>'LAP-001','name'=>'Laptop professionnel 14 pouces','quantity'=>24,'minimum_stock'=>10,'unit_price'=>899.00,'location'=>'Entrepôt A']);$p2=Product::create(['supplier_id'=>$s1->id,'sku'=>'DOCK-002','name'=>'Station d’accueil USB-C','quantity'=>4,'minimum_stock'=>8,'unit_price'=>129.90,'location'=>'Entrepôt A']);$p3=Product::create(['supplier_id'=>$s2->id,'sku'=>'CAB-003','name'=>'Câble réseau Cat6 2m','quantity'=>87,'minimum_stock'=>20,'unit_price'=>8.50,'location'=>'Rayon C2']);foreach([[$p1,24],[$p2,4],[$p3,87]] as [$p,$q])StockMovement::create(['product_id'=>$p->id,'type'=>'in','quantity'=>$q,'reason'=>'Stock initial']);Order::create(['supplier_id'=>$s1->id,'reference'=>'CMD-2026-001','status'=>'sent','ordered_at'=>now()->subDays(2),'notes'=>'Réassort stations USB-C']);}}
